import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:printing/printing.dart';

/// The report stays on the device; PDF.js renders the generated bytes on Web.
class ActivityPdfPreview extends StatefulWidget {
  const ActivityPdfPreview({
    super.key,
    required this.bytes,
    required this.fileName,
  });

  final Uint8List bytes;
  final String fileName;

  @override
  State<ActivityPdfPreview> createState() => _ActivityPdfPreviewState();
}

class _ActivityPdfPreviewState extends State<ActivityPdfPreview> {
  late final Future<PrintingInfo> _ready = Printing.info().timeout(
    const Duration(seconds: 15),
  );

  Widget _error() => const Center(
    child: Padding(
      padding: EdgeInsets.all(24),
      child: Text(
        'Chưa hiển thị được PDF. Bạn có thể đóng cửa sổ và chọn Xuất hồ sơ PDF, hoặc tải lại trang để thử lại.',
        textAlign: TextAlign.center,
      ),
    ),
  );

  @override
  Widget build(BuildContext context) => Dialog.fullscreen(
    child: Scaffold(
      appBar: AppBar(
        leading: IconButton(
          tooltip: 'Đóng bản xem trước',
          onPressed: () => Navigator.of(context).pop(),
          icon: const Icon(Icons.close),
        ),
        title: const Text('Hồ sơ hoạt động'),
      ),
      body: FutureBuilder<PrintingInfo>(
        future: _ready,
        builder: (context, snapshot) {
          if (snapshot.hasError) return _error();
          if (!snapshot.hasData) {
            return const Center(child: CircularProgressIndicator());
          }
          if (!snapshot.data!.canRaster) return _error();
          return PdfPreview(
            build: (_) async => widget.bytes,
            pdfFileName: widget.fileName,
            maxPageWidth: 850,
            canChangePageFormat: false,
            canChangeOrientation: false,
            canDebug: false,
            onError: (context, error) => _error(),
          );
        },
      ),
    ),
  );
}
